def role_for_path(path: str, is_folder: bool = False) -> str:
    name = path.lower().strip("/")
    if is_folder:
        if name in {"src"}:
            return "Where the main implementation lives"
        if name in {"lib"}:
            return "Reusable implementation code"
        if name in {"app", "apps"}:
